import React, { useState, useEffect, useLayoutEffect, Suspense, useRef } from 'react';
import { getCurrentHash, setHash } from '../utils/hash';
import { getApiRoot } from '../utils/api';
import { isFeatureAvailable } from '../utils/planFeatures';
import ProOverlay from './ProOverlay';

const LazyReactQuill = React.lazy(async () => {
  await import('react-quill/dist/quill.snow.css');
  const mod = await import('react-quill');
  return { default: mod.default };
});

const DEFAULT_EMAIL_SUBJECT = 'AFM File Log Recent Activity';

const resolveEmailSubject = (subject) => {
  const trimmed = typeof subject === 'string' ? subject.trim() : '';
  return trimmed || DEFAULT_EMAIL_SUBJECT;
};

export default function NotificationsPanel({ onContentReady } = {}) {
  const root = getApiRoot();
  const nonce = window.wpApiSettings?.nonce || window.afmReact?.nonce || '';
  const notificationsEndpoint = (params = null) => {
    const base = `${root}file-manager-advanced/v1/notifications`;
    if (!params || typeof params !== 'object') return base;
    const query = new URLSearchParams(params).toString();
    if (!query) return base;
    return `${base}${base.includes('?') ? '&' : '?'}${query}`;
  };

  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!loading) onContentReady?.();
  }, [loading, onContentReady]);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState(null);

  // Initialize with default, then use useLayoutEffect to set correct value immediately
  const [activeSubTab, setActiveSubTab] = useState('email');
  const [emailEnabled, setEmailEnabled] = useState(false);
  const [slackEnabled, setSlackEnabled] = useState(false);
  const [emailAddress, setEmailAddress] = useState('');
  const [emailSubject, setEmailSubject] = useState('');
  // Helper function to convert plain text with \n to HTML for ReactQuill
  const textToHtml = (text) => {
    if (!text) return '';
    return text.split('\n\n').map(para => `<p>${para.split('\n').join('<br>')}</p>`).join('');
  };

  // Helper function to convert HTML back to plain text for saving
  const htmlToText = (html) => {
    if (!html) return '';
    // Convert <p> tags to double newlines and <br> to single newlines
    return html
      .replace(/<p>/g, '')
      .replace(/<\/p>/g, '\n\n')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/&nbsp;/g, ' ')
      .trim();
  };

  const [emailMessage, setEmailMessage] = useState(textToHtml('Hi {admin_email},\n\nA quick update from the Advanced File Manager plugin on your site {site_name}.\nA {item_type} was {event} by {username} on {date_time}. The {item_type} name is {file_name} with the extension {ext}, and the action was performed from the following IP Address: {ip_address}.'));
  const [slackMessage, setSlackMessage] = useState(textToHtml('Hi {admin_email},\n\nA quick update from the Advanced File Manager plugin on your site {site_name}.\nA {item_type} was {event} by {username} on {date_time}. The {item_type} name is {file_name} with the extension {ext}, and the action was performed from the following IP Address: {ip_address}.'));
  const [slackWebhookUrl, setSlackWebhookUrl] = useState('');
  const [emailEvents, setEmailEvents] = useState([]);
  const [slackEvents, setSlackEvents] = useState([]);

  const hasPro = window.afmReact?.hasPro || false;
  const hasActiveSmtpPlugin = !!window.afmReact?.hasActiveSmtpPlugin;
  const currentPlan = window.afmReact?.currentPlan || 'free';
  const pricingUrl = window.afmReact?.pricingUrl || 'https://advancedfilemanager.com/pricing/';
  const smtpSettingsUrl = window.afmReact?.smtpSettingsUrl
    || `${window.location.origin}/wp-admin/admin.php?page=file-manager-advanced-recommend-post-smtp`;
  const smtpEmbedUrl = smtpSettingsUrl + (smtpSettingsUrl.includes('?') ? '&' : '?') + 'afm_embed=1';
  const isNotifSubTab = (tab) => tab === 'email' || tab === 'slack' || tab === 'smtp';

  // Check plan-based feature availability
  const slackNotificationAvailable = isFeatureAvailable('slack_notification', currentPlan, hasPro);

  // Free (no Pro): show Email + Slack toggles ON and full forms as read-only demo (saves stay blocked).
  const notificationsFreeDemo = !hasPro;
  const emailToggleDisplayed = notificationsFreeDemo || emailEnabled;
  const slackToggleDisplayed = notificationsFreeDemo || slackEnabled;
  const showEmailDetailSections = notificationsFreeDemo || emailEnabled;
  const showSlackDetailSections =
    (notificationsFreeDemo || slackEnabled) &&
    (notificationsFreeDemo || slackNotificationAvailable);

  // Use useLayoutEffect to read hash synchronously before paint
  // This ensures we get the correct hash before any other effects run
  // Priority: sessionStorage > hash (because elFinder might have changed hash)
  useLayoutEffect(() => {
    // FIRST: Check sessionStorage - this is most reliable because we saved it
    const savedSubTab = sessionStorage.getItem('afm-notifications-subtab');

    if (isNotifSubTab(savedSubTab) && (savedSubTab !== 'smtp' || !hasActiveSmtpPlugin)) {
      setActiveSubTab(savedSubTab);
      return;
    }

    // SECOND: Check hash if sessionStorage doesn't have it
    const rawHash = window.location.hash || '';
    const hash = rawHash.replace(/^#/, '').replace(/^\//, '');

    // If hash has sub-tab, use it immediately
    if (hash.startsWith('notifications/')) {
      const parts = hash.split('/');
      if (parts.length > 1) {
        const subTab = parts[1].split('?')[0].toLowerCase();
        if (isNotifSubTab(subTab) && (subTab !== 'smtp' || !hasActiveSmtpPlugin)) {
          sessionStorage.setItem('afm-notifications-subtab', subTab);
          setActiveSubTab(subTab);
          return;
        }
      }
    }

    // If hash is just 'notifications', default to email
    if (hash === 'notifications') {
      sessionStorage.setItem('afm-notifications-subtab', 'email');
      setActiveSubTab('email');
      return;
    }

    // Default to email
    sessionStorage.setItem('afm-notifications-subtab', 'email');
    setActiveSubTab('email');
  }, []); // Only run once on mount

  // Save sub-tab to sessionStorage
  useEffect(() => {
    if (activeSubTab) {
      sessionStorage.setItem('afm-notifications-subtab', activeSubTab);
    }
  }, [activeSubTab]);

  // Function to fix hash if it's missing sub-tab
  const fixNotificationsHash = () => {
    const hash = getCurrentHash();

    // If hash is just 'notifications' without sub-tab, add sub-tab
    if (hash === 'notifications') {
      const savedSubTab = sessionStorage.getItem('afm-notifications-subtab');
      const subTabToUse = isNotifSubTab(savedSubTab) ? savedSubTab : 'email';

      // Update URL immediately
      const urlHash = `#/notifications/${subTabToUse}`;
      if (window.history && window.history.replaceState) {
        const url = window.location.href.split('#')[0] + urlHash;
        window.history.replaceState(null, '', url);
      } else {
        window.location.hash = urlHash;
      }

      // Update state if needed
      if (activeSubTab !== subTabToUse) {
        setActiveSubTab(subTabToUse);
      }
    }
  };

  // Listen for hash changes and sync sub-tab
  useEffect(() => {
    const syncSubTabFromHash = () => {
      // Read directly from window.location.hash to ensure we get the actual current value
      const rawHash = window.location.hash || '';
      const hash = rawHash.replace(/^#/, '').replace(/^\//, '');

      // If hash already has sub-tab (notifications/email|slack|smtp), use it
      if (hash.startsWith('notifications/')) {
        const parts = hash.split('/');
        if (parts.length > 1) {
          const subTab = parts[1].split('?')[0].toLowerCase();
          if (isNotifSubTab(subTab) && (subTab !== 'smtp' || !hasActiveSmtpPlugin)) {
            sessionStorage.setItem('afm-notifications-subtab', subTab);
            setActiveSubTab(prev => prev !== subTab ? subTab : prev);
            return;
          }
        }
      }

      // If hash is just 'notifications' (without sub-tab), fix it
      if (hash === 'notifications') {
        const savedSubTab = sessionStorage.getItem('afm-notifications-subtab') || 'email';
        const subTabToUse = isNotifSubTab(savedSubTab) ? savedSubTab : 'email';

        // Update URL immediately
        const urlHash = `#/notifications/${subTabToUse}`;
        if (window.history && window.history.replaceState) {
          const url = window.location.href.split('#')[0] + urlHash;
          window.history.replaceState(null, '', url);
        } else {
          window.location.hash = urlHash;
        }

        // Update state
        setActiveSubTab(prev => prev !== subTabToUse ? subTabToUse : prev);
      }
    };

    // Listen for hash changes
    window.addEventListener('hashchange', syncSubTabFromHash);

    return () => {
      window.removeEventListener('hashchange', syncSubTabFromHash);
    };
  }, []); // Only run on mount, hash changes will trigger hashchange event

  // Update URL hash when sub-tab changes (but not on initial mount to avoid overriding URL)
  const isInitialMountRef = useRef(true);
  useEffect(() => {
    // Skip URL update on initial mount - let the URL hash drive the initial state
    if (isInitialMountRef.current) {
      isInitialMountRef.current = false;
      return;
    }

    const hash = `#/notifications/${activeSubTab}`;
    if (window.history && window.history.replaceState) {
      const url = window.location.href.split('#')[0] + hash;
      window.history.replaceState(null, '', url);
    } else {
      window.location.hash = hash;
    }
  }, [activeSubTab]);

  // Available events
  const events = [
    { value: 'rm', label: 'Delete File/Folder' },
    { value: 'mkfile', label: 'Create File' },
    { value: 'mkdir', label: 'Create Folder' }
  ];

  // Placeholders for both email and Slack
  const placeholders = [
    { code: '{username}', desc: 'This will fetch the user\'s name who did the action' },
    { code: '{ip_address}', desc: 'This will fetch the user\'s IP Address' },
    { code: '{event}', desc: 'This will fetch which action the user performed (created/deleted)' },
    { code: '{item_type}', desc: 'This will fetch whether the target is a file or folder' },
    { code: '{file_name}', desc: 'This will fetch the file name on which that action was done' },
    { code: '{ext}', desc: 'This will fetch the extension or mime type for the target item' },
    { code: '{date_time}', desc: 'This will fetch the date the user acted on the file' },
    { code: '{site_name}', desc: 'This will fetch the site name on which the action was performed' }
  ];

  // Fetch notifications data and handle webhook_url return
  useEffect(() => {
    if (!root || !nonce) {
      console.warn('AFM Notifications: Missing API root or nonce');
      return;
    }

    // Check if webhook_url is in URL parameters (returning from slack.advancedfilemanager.com)
    const urlParams = new URLSearchParams(window.location.search);
    const webhookUrl = urlParams.get('webhook_url');

    let requestChain = Promise.resolve();

    if (webhookUrl) {
      // Auto-save webhook URL via API
      requestChain = fetch(notificationsEndpoint(), {
        method: 'POST',
        credentials: 'same-origin',
        headers: {
          'X-WP-Nonce': nonce,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          slack: {
            webhook_url: decodeURIComponent(webhookUrl),
            enable: 'yes'
          }
        })
      })
        .then(() => {
          // Remove webhook_url from URL to clean it up
          const newUrl = window.location.href.split('&webhook_url=')[0].split('?webhook_url=')[0];
          window.history.replaceState({}, '', newUrl);
        })
        .catch(err => {
          console.error('AFM Notifications webhook save error:', err);
        });
    }

    // Fetch data after potential webhook save
    requestChain.then(() => {
      // Add a small delay to ensure DB write propagation
      setTimeout(() => {
        fetch(notificationsEndpoint({ _t: String(Date.now()) }), {
          credentials: 'same-origin',
          headers: { 'X-WP-Nonce': nonce }
        })
          .then(r => r.ok ? r.json() : Promise.reject('Failed to fetch'))
          .then(res => {
            setData(res);
            setEmailEnabled(res?.email?.enable === 'yes');
            setSlackEnabled(res?.slack?.enable === 'yes');
            // Set email fields with defaults
            setEmailAddress(res?.email?.email || '');
            setEmailSubject(resolveEmailSubject(res?.email?.subject));
            // Set email events
            setEmailEvents(Array.isArray(res?.email?.events) ? res.email.events : []);
            // Convert plain text to HTML for ReactQuill
            const emailMsg = res?.email?.message || 'Hi {admin_email},\n\nA quick update from the Advanced File Manager plugin on your site {site_name}.\nA {item_type} was {event} by {username} on {date_time}. The {item_type} name is {file_name} with the extension {ext}, and the action was performed from the following IP Address: {ip_address}.';
            setEmailMessage(emailMsg.includes('<p>') || emailMsg.includes('<br>') ? emailMsg : textToHtml(emailMsg));
            // Set slack fields with defaults
            setSlackEvents(Array.isArray(res?.slack?.events) ? res.slack.events : []);
            const slackMsg = res?.slack?.message || 'Hi {admin_email},\n\nA quick update from the Advanced File Manager plugin on your site {site_name}.\nA {item_type} was {event} by {username} on {date_time}. The {item_type} name is {file_name} with the extension {ext}, and the action was performed from the following IP Address: {ip_address}.';
            setSlackMessage(slackMsg.includes('<p>') || slackMsg.includes('<br>') ? slackMsg : textToHtml(slackMsg));
            // Set webhook URL from response or from URL parameter (fallback)
            const webhookFromUrl = webhookUrl ? decodeURIComponent(webhookUrl) : '';
            setSlackWebhookUrl(webhookFromUrl || res?.slack?.webhook_url || '');
            setLoading(false);
          })
          .catch(err => {
            console.error('AFM Notifications fetch error:', err);
            setLoading(false);
          });
      }, 500);
    });
  }, [root, nonce]);

  // Save handler - separated to allow calling with overrides
  const handleSave = (e, overrideData = null) => {
    if (e && e.preventDefault) e.preventDefault();
    if (!hasPro) {
      alert('Pro version is required for notifications.');
      return;
    }

    if (!data || saving) return;
    setSaving(true);
    setMessage(null);

    // Use state for events instead of formData to ensure both email and slack events are always included
    // Merge overrideData if provided
    const submitData = {
      email: {
        enable: emailEnabled ? 'yes' : 'no',
        email: emailAddress || '',
        events: emailEvents || [], // Use state directly
        subject: resolveEmailSubject(emailSubject),
        message: htmlToText(emailMessage) || '',
        ...(overrideData?.email || {})
      },
      slack: {
        enable: slackEnabled ? 'yes' : 'no',
        webhook_url: slackWebhookUrl || '',
        events: slackEvents || [], // Use state directly
        message: htmlToText(slackMessage) || '',
        ...(overrideData?.slack || {})
      }
    };

    fetch(notificationsEndpoint(), {
      method: 'POST',
      credentials: 'same-origin',
      headers: {
        'X-WP-Nonce': nonce,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(submitData)
    })
      .then(r => r.ok ? r.json() : Promise.reject(r))
      .then(res => {
        setMessage({ type: 'success', text: res.message || 'Notification settings saved successfully.' });
        setSaving(false);
        // Auto-hide message after 5 seconds
        setTimeout(() => setMessage(null), 5000);
        // Refresh data
        return fetch(notificationsEndpoint(), {
          credentials: 'same-origin',
          headers: { 'X-WP-Nonce': nonce }
        });
      })
      .then(r => r.ok ? r.json() : Promise.reject(r))
      .then(res => {
        setData(res);
        setEmailEnabled(res?.email?.enable === 'yes');
        setSlackEnabled(res?.slack?.enable === 'yes');
        // Set email fields with defaults
        setEmailAddress(res?.email?.email || '');
        setEmailSubject(resolveEmailSubject(res?.email?.subject));
        // Set email events
        setEmailEvents(Array.isArray(res?.email?.events) ? res.email.events : []);
        // Convert plain text to HTML for ReactQuill
        const emailMsg = res?.email?.message || 'Hi {admin_email},\n\nA quick update from the Advanced File Manager plugin on your site {site_name}.\nA {item_type} was {event} by {username} on {date_time}. The {item_type} name is {file_name} with the extension {ext}, and the action was performed from the following IP Address: {ip_address}.';
        setEmailMessage(emailMsg.includes('<p>') || emailMsg.includes('<br>') ? emailMsg : textToHtml(emailMsg));
        // Set slack fields with defaults
        setSlackEvents(Array.isArray(res?.slack?.events) ? res.slack.events : []);
        const slackMsg = res?.slack?.message || 'Hi {admin_email},\n\nA quick update from the Advanced File Manager plugin on your site {site_name}.\nA {item_type} was {event} by {username} on {date_time}. The {item_type} name is {file_name} with the extension {ext}, and the action was performed from the following IP Address: {ip_address}.';
        setSlackMessage(slackMsg.includes('<p>') || slackMsg.includes('<br>') ? slackMsg : textToHtml(slackMsg));
        // Set webhook URL
        setSlackWebhookUrl(res?.slack?.webhook_url || '');
      })
      .catch(err => {
        console.error('AFM Notifications save error:', err);
        setMessage({ type: 'error', text: err.message || 'Failed to save notification settings.' });
        setSaving(false);
        // Auto-hide error message after 5 seconds
        setTimeout(() => setMessage(null), 5000);
      });
  };

  // Form submit handler wrapper
  const handleSubmit = (e) => handleSave(e);

  if (loading) {
    return (
      <div className="afm-tab-panel" style={{ padding: '20px' }}>
        <style>{`
          @keyframes afm-skeleton-shimmer {
            0% { background-position: -200% 0; }
            100% { background-position: 200% 0; }
          }
          .afm-skeleton {
            background-color: #e2e8f0;
            background-image: linear-gradient(90deg, #e2e8f0 0%, #f1f5f9 50%, #e2e8f0 100%);
            background-size: 200% 100%;
            animation: afm-skeleton-shimmer 1.4s linear infinite;
          }
        `}</style>
        <div style={{ background: '#fff', border: '1px solid #ccc', padding: '20px' }}>
          <div className="afm-skeleton" style={{ height: '34px', width: '100%', borderRadius: '6px', marginBottom: '18px' }} />
          <div className="afm-skeleton" style={{ height: '20px', width: '220px', borderRadius: '6px', marginBottom: '16px' }} />
          <div className="afm-skeleton" style={{ height: '42px', width: '100%', borderRadius: '6px', marginBottom: '12px' }} />
          <div className="afm-skeleton" style={{ height: '42px', width: '100%', borderRadius: '6px', marginBottom: '12px' }} />
          <div className="afm-skeleton" style={{ height: '120px', width: '100%', borderRadius: '6px', marginBottom: '12px' }} />
          <div className="afm-skeleton" style={{ height: '42px', width: '160px', borderRadius: '6px', marginTop: '10px' }} />
        </div>
      </div>
    );
  }

  const emailData = data?.email || {};
  const slackData = data?.slack || {};
  const showSaveButton =
    hasPro &&
    ((activeSubTab === 'email' && emailEnabled) ||
      (activeSubTab === 'slack' && slackEnabled && slackNotificationAvailable));

  // Toggle component
  const Toggle = ({ id, name, checked, disabled, onChange }) => (
    <label
      onClick={(e) => {
        if (!disabled && onChange) {
          e.preventDefault();
          e.stopPropagation();
          onChange({ target: { checked: !checked } });
        }
      }}
      style={{
        display: 'inline-block',
        cursor: disabled ? 'not-allowed' : 'pointer',
        opacity: disabled ? 0.5 : 1,
        margin: 0,
        padding: 0,
        userSelect: 'none'
      }}
    >
      <input
        type="checkbox"
        id={id}
        name={name}
        value="yes"
        checked={checked}
        disabled={disabled}
        readOnly
        style={{ display: 'none' }}
      />
      <div style={{
        position: 'relative',
        width: '44px',
        height: '24px',
        background: checked ? '#3F6972' : '#ccc',
        borderRadius: '12px',
        transition: 'background 0.3s',
        pointerEvents: disabled ? 'none' : 'auto'
      }}>
        <div style={{
          position: 'absolute',
          top: '2px',
          left: checked ? '22px' : '2px',
          width: '20px',
          height: '20px',
          background: '#fff',
          borderRadius: '50%',
          transition: 'left 0.3s',
          boxShadow: '0 2px 4px rgba(0,0,0,0.2)'
        }} />
      </div>
    </label>
  );

  return (
    <div className="afm-tab-panel">
      <div className="wrap" style={{ background: '#fff', padding: '20px', border: '1px solid #ccc', position: 'relative' }}>
        {/* Sub-tabs - same style as Settings */}
        <h2 className="nav-tab-wrapper afm-clean-tabs" style={{ marginBottom: '20px', borderBottom: 'none' }}>
          <a
            href="#/notifications/email"
            onClick={(e) => {
              e.preventDefault();
              setActiveSubTab('email');
              // Update URL hash immediately
              const urlHash = `#/notifications/email`;
              if (window.history && window.history.replaceState) {
                const url = window.location.href.split('#')[0] + urlHash;
                window.history.replaceState(null, '', url);
              } else {
                window.location.hash = urlHash;
              }
            }}
            className={`nav-tab afm-clean-tab ${activeSubTab === 'email' ? ' nav-tab-active' : ''}`}
          >
            Email Notifications
            {!hasPro && (
              <span style={{
                marginLeft: '6px',
                background: '#3F6972',
                color: '#fff',
                fontSize: '10px',
                fontWeight: 700,
                padding: '2px 6px',
                borderRadius: '10px',
                textTransform: 'uppercase'
              }}>PRO</span>
            )}
          </a>
          <a
            href="#/notifications/slack"
            onClick={(e) => {
              e.preventDefault();
              setActiveSubTab('slack');
              // Update URL hash immediately
              const urlHash = `#/notifications/slack`;
              if (window.history && window.history.replaceState) {
                const url = window.location.href.split('#')[0] + urlHash;
                window.history.replaceState(null, '', url);
              } else {
                window.location.hash = urlHash;
              }
            }}
            className={`nav-tab afm-clean-tab ${activeSubTab === 'slack' ? ' nav-tab-active' : ''}`}
          >
            Slack Notifications
            {(!hasPro || (hasPro && !slackNotificationAvailable)) && (
              <span style={{
                marginLeft: '6px',
                background: '#3F6972',
                color: '#fff',
                fontSize: '10px',
                fontWeight: 700,
                padding: '6px',
                borderRadius: '10px',
                textTransform: 'uppercase'
              }}>PRO</span>
            )}
          </a>
          {!hasActiveSmtpPlugin && (
            <a
              href="#/notifications/smtp"
              onClick={(e) => {
                e.preventDefault();
                setActiveSubTab('smtp');
                const urlHash = `#/notifications/smtp`;
                if (window.history && window.history.replaceState) {
                  const url = window.location.href.split('#')[0] + urlHash;
                  window.history.replaceState(null, '', url);
                } else {
                  window.location.hash = urlHash;
                }
              }}
              className={`nav-tab afm-clean-tab ${activeSubTab === 'smtp' ? ' nav-tab-active' : ''}`}
            >
              SMTP
              <span style={{
                marginLeft: '6px',
                background: '#16a34a',
                color: '#fff',
                fontSize: '10px',
                fontWeight: 700,
                padding: '2px 6px',
                borderRadius: '10px',
                textTransform: 'uppercase'
              }}>RECOMMENDED</span>
            </a>
          )}
        </h2>

          {/* Snackbar message - same style as Settings */}
          {message && (
            <div
              className={`afm-snackbar afm-snackbar-${message.type === 'success' ? 'success' : 'error'}`}
              onClick={() => setMessage(null)}
              style={{ animation: 'afm-slideIn 0.3s ease-out' }}
            >
              <span style={{ fontSize: '14px', lineHeight: '1.5', flex: '1' }}>{message.text}</span>
              <button
                type="button"
                className="afm-snackbar-close"
                onClick={(e) => { e.preventDefault(); e.stopPropagation(); setMessage(null); }}
                style={{ background: 'none', border: 'none', padding: '0', cursor: 'pointer', color: 'inherit', fontSize: '18px', lineHeight: '1', marginLeft: '12px', opacity: '0.7', width: '20px', height: '20px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
              >
                ×
              </button>
            </div>
          )}

          {activeSubTab === 'smtp' && !hasActiveSmtpPlugin && (
            <iframe
              title="SMTP"
              src={smtpEmbedUrl}
              style={{ width: '100%', minHeight: '720px', border: '0', display: 'block' }}
            />
          )}

          {activeSubTab !== 'smtp' && (
          <form onSubmit={handleSubmit}>
            {/* Email Notification Sub-tab */}
            {activeSubTab === 'email' && (
              <ProOverlay shouldShow={!hasPro}>
              <div>
                {/* Header with icon and toggle */}
                <div style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'flex-start',
                  marginBottom: emailToggleDisplayed ? '30px' : '0',
                  paddingBottom: emailToggleDisplayed ? '15px' : '0',
                  borderBottom: emailToggleDisplayed ? '1px solid #e5e5e5' : 'none',
                  gap: '80px'
                }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                    <img
                      src={(window.afmReact?.pluginUrl || window.afm_object?.plugin_url || '/wp-content/plugins/file-manager-advanced/') + 'application/assets/images/email_notification.svg'}
                      alt="Email Notifications"
                      style={{
                        width: '24px',
                        height: '24px',
                        flexShrink: 0
                      }}
                    />
                    <h3 style={{ margin: 0, fontSize: '18px', fontWeight: 600, color: '#0f172a' }}>
                      Email Notifications
                    </h3>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', margin: 0, padding: 0 }}>
                    <Toggle
                      id="email_enable"
                      name="email_enable"
                      checked={emailToggleDisplayed}
                      disabled={!hasPro}
                      onChange={(e) => {
                        const newValue = !emailEnabled;
                        setEmailEnabled(newValue);
                        // Auto-save when toggled
                        handleSave(null, { email: { enable: newValue ? 'yes' : 'no' } });
                      }}
                    />
                  </div>
                </div>

                {/* Sections - only show if enabled (free: always expanded as demo) */}
                {showEmailDetailSections && (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '30px' }}>
                    {/* Emails Section */}
                    <div>
                      <h4 style={{ marginBottom: '12px', fontSize: '16px', fontWeight: 600, color: '#0f172a' }}>
                        Emails
                      </h4>
                      <input
                        type="email"
                        id="email_address"
                        name="email_address"
                        value={emailAddress}
                        onChange={(e) => setEmailAddress(e.target.value)}
                        disabled={!hasPro}
                        placeholder="Enter email address"
                        style={{
                          width: '100%',
                          maxWidth: '500px',
                          padding: '10px 12px',
                          border: '1px solid #ddd',
                          borderRadius: '4px',
                          fontSize: '14px'
                        }}
                      />
                      <p style={{ marginTop: '8px', marginBottom: 0, fontSize: '13px', color: '#666' }}>
                        Email address to send notification.
                      </p>
                    </div>

                    {/* Events Section */}
                    <div>
                      <h4 style={{ marginBottom: '12px', fontSize: '16px', fontWeight: 600, color: '#0f172a' }}>
                        Events Notification
                      </h4>
                      <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                        {events.map(event => (
                          <label key={event.value} style={{
                            display: 'flex',
                            alignItems: 'center',
                            cursor: !hasPro ? 'not-allowed' : 'pointer',
                            opacity: !hasPro ? 0.5 : 1,
                            userSelect: 'none'
                          }}>
                            <input
                              type="checkbox"
                              name="email_events[]"
                              value={event.value}
                              checked={emailEvents.includes(event.value)}
                              onChange={(e) => {
                                if (e.target.checked) {
                                  setEmailEvents([...emailEvents, event.value]);
                                } else {
                                  setEmailEvents(emailEvents.filter(ev => ev !== event.value));
                                }
                              }}
                              disabled={!hasPro}
                              style={{
                                marginRight: '10px',
                                width: '18px',
                                height: '18px',
                                cursor: !hasPro ? 'not-allowed' : 'pointer',
                                accentColor: '#3F6972'
                              }}
                            />
                            <span style={{ fontSize: '14px', color: '#0f172a' }}>{event.label}</span>
                          </label>
                        ))}
                      </div>
                    </div>

                    {/* Emails Subject Section */}
                    <div>
                      <h4 style={{ marginBottom: '12px', fontSize: '16px', fontWeight: 600, color: '#0f172a' }}>
                        Emails Subject
                      </h4>
                      <input
                        type="text"
                        id="email_subject"
                        name="email_subject"
                        value={emailSubject}
                        onChange={(e) => setEmailSubject(e.target.value)}
                        disabled={!hasPro}
                        placeholder={DEFAULT_EMAIL_SUBJECT}
                        style={{
                          width: '100%',
                          maxWidth: '500px',
                          padding: '10px 12px',
                          border: '1px solid #ddd',
                          borderRadius: '4px',
                          fontSize: '14px'
                        }}
                      />
                      <p style={{ marginTop: '8px', marginBottom: 0, fontSize: '13px', color: '#666' }}>
                        Subject of the email notification.
                      </p>
                    </div>

                    {/* Emails Message Section */}
                    <div>
                      <h4 style={{ marginBottom: '12px', fontSize: '16px', fontWeight: 600, color: '#0f172a' }}>
                        Emails Message
                      </h4>
                      {/* Rich text editor */}
                      <div style={{ maxWidth: '800px' }}>
                        <Suspense fallback={<div style={{ padding: '12px', color: '#666' }}>Loading editor...</div>}>
                          <LazyReactQuill
                            theme="snow"
                            value={emailMessage}
                            onChange={setEmailMessage}
                            readOnly={!hasPro}
                            modules={{
                              toolbar: [
                                ['bold', 'italic', 'underline', 'strike'],
                                [{ 'color': [] }, { 'background': [] }, 'clean'],
                                [{ 'header': [1, 2, 3, 4, false] }],
                                [{ 'list': 'ordered' }, { 'list': 'bullet' }],
                                ['link', 'image'],
                                [{ 'script': 'sub' }, { 'script': 'super' }],
                                [{ 'align': [] }]
                              ]
                            }}
                            formats={[
                              'bold', 'italic', 'underline', 'strike',
                              'color', 'background',
                              'header',
                              'list', 'bullet',
                              'link', 'image',
                              'script',
                              'align'
                            ]}
                            style={{
                              backgroundColor: '#fff'
                            }}
                          />
                        </Suspense>
                        {/* Hidden input for form submission */}
                        <input
                          type="hidden"
                          name="email_message"
                          value={emailMessage}
                        />
                      </div>
                      <p style={{ marginTop: '8px', marginBottom: '12px', fontSize: '13px', color: '#666' }}>
                        Message body of the email notification. You can use placeholders like {`{file_name}`}, {`{action}`} etc.
                      </p>
                      <div style={{
                        background: '#f8f9fa',
                        padding: '15px',
                        borderRadius: '4px',
                        border: '1px solid #e5e5e5',
                        marginTop: '12px'
                      }}>
                        <p style={{ marginBottom: '10px', fontSize: '14px', fontWeight: 600, color: '#0f172a' }}>
                          Available placeholders:
                        </p>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                          {placeholders.map((ph, i) => (
                            <div key={i} style={{ fontSize: '13px', color: '#495057', lineHeight: '1.5' }}>
                              <code style={{
                                background: '#e9ecef',
                                padding: '2px 6px',
                                borderRadius: '3px',
                                fontFamily: 'monospace',
                                fontSize: '12px',
                                color: '#0f172a'
                              }}>{ph.code}</code>
                              <span style={{ marginLeft: '8px' }}>- {ph.desc}</span>
                            </div>
                          ))}
                        </div>
                      </div>
                    </div>
                  </div>
                )}
              </div>
              </ProOverlay>
            )}

            {/* Slack Notification Sub-tab */}
            {activeSubTab === 'slack' && (
              <ProOverlay shouldShow={!hasPro || !slackNotificationAvailable}>
                <div>
                  {/* Header with icon and toggle */}
                  <div style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'flex-start',
                    marginBottom: slackToggleDisplayed ? '30px' : '0',
                    paddingBottom: slackToggleDisplayed ? '15px' : '0',
                    borderBottom: slackToggleDisplayed ? '1px solid #e5e5e5' : 'none',
                    gap: '80px'
                  }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                      <img
                        src={(window.afmReact?.pluginUrl || window.afm_object?.plugin_url || '/wp-content/plugins/file-manager-advanced/') + 'application/assets/images/slack_notification.svg'}
                        alt="Slack Notifications"
                        style={{
                          width: '24px',
                          height: '24px',
                          flexShrink: 0
                        }}
                      />
                      <h3 style={{ margin: 0, fontSize: '18px', fontWeight: 600, color: '#0f172a' }}>
                        Slack Notifications
                      </h3>
                    </div>
                    <div style={{ display: 'flex', alignItems: 'center', margin: 0, padding: 0 }}>
                      <Toggle
                        id="slack_enable"
                        name="slack_enable"
                        checked={slackToggleDisplayed}
                        disabled={!hasPro || !slackNotificationAvailable}
                        onChange={(e) => {
                          const newValue = !slackEnabled;
                          setSlackEnabled(newValue);
                          // Auto-save when toggled
                          handleSave(null, { slack: { enable: newValue ? 'yes' : 'no' } });
                        }}
                      />
                    </div>
                  </div>

                  {/* Sections: Pro + plan allows Slack, or free demo */}
                  {showSlackDetailSections && (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '30px' }}>
                      {/* Slack Webhook URL Section */}
                      <div>
                        <h4 style={{ marginBottom: '12px', fontSize: '16px', fontWeight: 600, color: '#0f172a' }}>
                          Slack Webhook URL
                        </h4>
                        <input
                          type="url"
                          id="slack_webhook_url"
                          name="slack_webhook_url"
                          value={slackWebhookUrl}
                          onChange={(e) => setSlackWebhookUrl(e.target.value)}
                          disabled={!hasPro || !slackNotificationAvailable}
                          placeholder="webhook.slack.com"
                          style={{
                            width: '100%',
                            maxWidth: '600px',
                            padding: '10px 12px',
                            border: '1px solid #ddd',
                            borderRadius: '4px',
                            fontSize: '14px'
                          }}
                        />
                        <p style={{ marginTop: '8px', marginBottom: '4px', fontSize: '13px', color: '#666' }}>
                          Enable your Slack Webhook URL to receive notifications.
                        </p>
                        <a
                          href={`https://slack.advancedfilemanager.com?install_application=true&redirect_to=${encodeURIComponent(
                            `${window.location.origin}/wp-admin/admin.php?page=file_manager_advanced_ui#/notifications/slack`
                          )}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          style={{ fontSize: '13px', color: '#3F6972', textDecoration: 'underline' }}
                        >
                          Click here to get your webhook URL
                        </a>
                      </div>

                      {/* Events Notification Section */}
                      <div>
                        <h4 style={{ marginBottom: '12px', fontSize: '16px', fontWeight: 600, color: '#0f172a' }}>
                          Events Notification
                        </h4>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                          {events.map(event => (
                            <label key={event.value} style={{
                              display: 'flex',
                              alignItems: 'center',
                              cursor: (!hasPro || !slackNotificationAvailable) ? 'not-allowed' : 'pointer',
                              opacity: (!hasPro || !slackNotificationAvailable) ? 0.5 : 1,
                              userSelect: 'none'
                            }}>
                              <input
                                type="checkbox"
                                name="slack_events[]"
                                value={event.value}
                                checked={slackEvents.includes(event.value)}
                                onChange={(e) => {
                                  if (e.target.checked) {
                                    setSlackEvents([...slackEvents, event.value]);
                                  } else {
                                    setSlackEvents(slackEvents.filter(ev => ev !== event.value));
                                  }
                                }}
                                disabled={!hasPro || !slackNotificationAvailable}
                                style={{
                                  marginRight: '10px',
                                  width: '18px',
                                  height: '18px',
                                  cursor: !hasPro ? 'not-allowed' : 'pointer',
                                  accentColor: '#3F6972'
                                }}
                              />
                              <span style={{ fontSize: '14px', color: '#0f172a' }}>{event.label}</span>
                            </label>
                          ))}
                        </div>
                      </div>

                      {/* Slack Message Section */}
                      <div>
                        <h4 style={{ marginBottom: '12px', fontSize: '16px', fontWeight: 600, color: '#0f172a' }}>
                          Slack Message
                        </h4>
                        {/* Rich text editor */}
                        <div style={{ maxWidth: '800px' }}>
                          <Suspense fallback={<div style={{ padding: '12px', color: '#666' }}>Loading editor...</div>}>
                          <LazyReactQuill
                            theme="snow"
                            value={slackMessage}
                            onChange={setSlackMessage}
                            readOnly={!hasPro || !slackNotificationAvailable}
                            modules={{
                              toolbar: [
                                ['bold', 'italic', 'underline', 'strike'],
                                [{ 'color': [] }, { 'background': [] }, 'clean'],
                                [{ 'header': [1, 2, 3, 4, false] }],
                                [{ 'list': 'ordered' }, { 'list': 'bullet' }],
                                ['link', 'image'],
                                [{ 'script': 'sub' }, { 'script': 'super' }],
                                [{ 'align': [] }]
                              ]
                            }}
                            formats={[
                              'bold', 'italic', 'underline', 'strike',
                              'color', 'background',
                              'header',
                              'list', 'bullet',
                              'link', 'image',
                              'script',
                              'align'
                            ]}
                            style={{
                              backgroundColor: '#fff'
                            }}
                          />
                          </Suspense>
                          {/* Hidden input for form submission */}
                          <input
                            type="hidden"
                            name="slack_message"
                            value={slackMessage}
                          />
                        </div>
                        <p style={{ marginTop: '8px', marginBottom: '12px', fontSize: '13px', color: '#666' }}>
                          Customize the message to be sent to Slack. You can use placeholders like {`{file_name}`}, {`{action}`}, etc.
                        </p>
                        <div style={{
                          background: '#f8f9fa',
                          padding: '15px',
                          borderRadius: '4px',
                          border: '1px solid #e5e5e5',
                          marginTop: '12px'
                        }}>
                          <p style={{ marginBottom: '10px', fontSize: '14px', fontWeight: 600, color: '#0f172a' }}>
                            Available placeholders:
                          </p>
                          <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                            {placeholders.map((ph, i) => (
                              <div key={i} style={{ fontSize: '13px', color: '#495057', lineHeight: '1.5' }}>
                                <code style={{
                                  background: '#e9ecef',
                                  padding: '2px 6px',
                                  borderRadius: '3px',
                                  fontFamily: 'monospace',
                                  fontSize: '12px',
                                  color: '#0f172a'
                                }}>{ph.code}</code>
                                <span style={{ marginLeft: '8px' }}>- {ph.desc}</span>
                              </div>
                            ))}
                          </div>
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              </ProOverlay>
            )}

            {showSaveButton && (
              <p className="submit" style={{ marginTop: '20px', paddingTop: '0' }}>
                <input
                  type="submit"
                  name="submit"
                  id="submit"
                  className="button button-primary afm-teal-button"
                  value={saving ? 'Saving...' : 'Save Changes'}
                  disabled={saving || !hasPro}
                />
              </p>
            )}
          </form>
          )}
      </div>
    </div >
  );
}
